'use client';

import { useState, type CSSProperties } from 'react';
import { toast } from 'sonner';
import { Checkbox } from '@/components/ui/checkbox';
import { cn } from '@/components/lib/utils';

type Paleta = {
  nome: string;
  vars: Record<string, string>;
  // cor de cada disciplina: [destaque, texto]
  disc: Record<string, [string, string]>;
};

const paletas: Paleta[] = [
  {
    nome: 'Café',
    vars: {
      '--bg': '#8A6A4B',
      '--rail': '#43281C',
      '--dot': '#FBF2C0',
      '--logo-bg': '#FBF2C0',
      '--logo-fg': '#C06E52',
      '--accent': '#C06E52',
      '--accent-fg': '#FFFFFF',
      '--soft': '#FBF2C0',
      '--line': '#E9D9A6',
      '--ink': '#43281C'
    },
    disc: {
      Matemática: ['#C06E52', '#7A3E2A'],
      Física: ['#8A6A4B', '#5C4430'],
      Inglês: ['#C9A227', '#6B5410'],
      Português: ['#43281C', '#43281C']
    }
  },
  {
    nome: 'Báltico',
    vars: {
      '--bg': '#381D2A',
      '--rail': '#AABD8C',
      '--dot': '#381D2A',
      '--logo-bg': '#381D2A',
      '--logo-fg': '#E9E3B4',
      '--accent': '#3E6990',
      '--accent-fg': '#FFFFFF',
      '--soft': '#E9E3B4',
      '--line': '#D6D0A0',
      '--ink': '#381D2A'
    },
    disc: {
      Matemática: ['#3E6990', '#2A4A68'],
      Física: ['#AABD8C', '#55663A'],
      Inglês: ['#C2B860', '#6A6324'],
      Português: ['#381D2A', '#381D2A']
    }
  },
  {
    nome: 'Gelo',
    vars: {
      '--bg': '#3FA9C4',
      '--rail': '#0E4450',
      '--dot': '#34F6F2',
      '--logo-bg': '#34F6F2',
      '--logo-fg': '#0E4450',
      '--accent': '#0E4450',
      '--accent-fg': '#D1F5FF',
      '--soft': '#EEF8FF',
      '--line': '#C6EEFA',
      '--ink': '#0E4450'
    },
    disc: {
      Matemática: ['#22DCD8', '#0B5E5C'],
      Física: ['#4FC8EE', '#0B4F63'],
      Inglês: ['#1FB8D6', '#0B4A57'],
      Português: ['#0B3B44', '#0B3B44']
    }
  }
];

const dias = ['Seg', 'Ter', 'Qua', 'Qui', 'Sex'];
const horas = ['15:00', '16:30', '18:00'];

// [dia, hora, disciplina, professor/sala]
const aulas: [number, number, string, string][] = [
  [0, 0, 'Matemática', 'Prof. Rita · Sala 1'],
  [0, 0, 'Física', 'Prof. Nuno · Sala 2'],
  [1, 0, 'Física', 'Prof. Nuno · Sala 2'],
  [1, 0, 'Português', 'Prof. Ana · Sala 3'],
  [2, 0, 'Matemática', 'Prof. Rita · Sala 1'],
  [2, 0, 'Matemática', 'Prof. Hugo · Sala 4'],
  [3, 0, 'Português', 'Prof. Ana · Sala 3'],
  [3, 0, 'Inglês', 'Prof. Sara · Sala 2'],
  [4, 0, 'Inglês', 'Prof. Sara · Sala 2'],
  [0, 1, 'Física', 'Prof. Nuno · Sala 2'],
  [0, 1, 'Matemática', 'Prof. Hugo · Sala 4'],
  [1, 1, 'Inglês', 'Prof. Sara · Sala 1'],
  [1, 1, 'Inglês', 'Prof. Sara · Sala 3'],
  [2, 1, 'Física', 'Prof. Nuno · Sala 2'],
  [2, 1, 'Matemática', 'Prof. Rita · Sala 1'],
  [3, 1, 'Inglês', 'Prof. Sara · Sala 2'],
  [3, 1, 'Física', 'Prof. Nuno · Sala 4'],
  [4, 1, 'Português', 'Prof. Ana · Sala 3'],
  [0, 2, 'Inglês', 'Prof. Sara · Sala 1'],
  [1, 2, 'Matemática', 'Prof. Rita · Sala 1'],
  [2, 2, 'Física', 'Prof. Nuno · Sala 2'],
  [3, 2, 'Português', 'Prof. Ana · Sala 3'],
  [4, 2, 'Matemática', 'Prof. Hugo · Sala 4']
];

const tarefas = [
  'Lançar sumários de ontem',
  'Ligar ao encarregado do João',
  'Confirmar sala 4 para sexta',
  'Enviar recibos de novembro',
  'Marcar teste de Física',
  'Rever faltas da semana'
];

const btn = 'rounded-lg border px-4 py-1.5 text-sm font-medium transition';
const ativo = 'border-(--accent) bg-(--accent) text-(--accent-fg)';
const inativo = 'border-(--line) bg-white text-(--ink) hover:bg-(--soft)';

export default function Page() {
  const [p, setP] = useState(0);
  const [aberta, setAberta] = useState(false);
  const [vista, setVista] = useState('Semana');
  const [filtro, setFiltro] = useState<string | null>(null);
  const [feitas, setFeitas] = useState<string[]>([]);
  const paleta = paletas[p];

  const toggle = (t: string) =>
    setFeitas((f) => (f.includes(t) ? f.filter((x) => x !== t) : [...f, t]));

  return (
    <div
      style={paleta.vars as CSSProperties}
      className='flex min-h-screen gap-4 bg-(--bg) p-4 text-(--ink) transition-colors'
    >
      {/* Rail lateral */}
      <aside
        className={cn(
          'flex shrink-0 flex-col gap-2 overflow-hidden rounded-2xl bg-(--rail) px-3 py-4 transition-[width] duration-300 ease-in-out',
          aberta ? 'w-52' : 'w-16'
        )}
      >
        <div className='mb-2 flex items-center gap-3'>
          <div className='flex size-10 shrink-0 items-center justify-center rounded-full bg-(--logo-bg) font-bold text-(--logo-fg)'>
            CE
          </div>
          <span
            className={cn(
              'font-bold whitespace-nowrap text-(--dot) transition-opacity duration-200',
              aberta ? 'opacity-100 delay-150' : 'opacity-0'
            )}
          >
            Centro de Estudo
          </span>
        </div>
        {['Horário', 'Alunos', 'Pagamentos', 'Mensagens'].map((n, i) => (
          <button
            key={n}
            title={n}
            className={cn(
              'flex items-center gap-3 rounded-xl px-2 py-2 text-left transition-colors hover:bg-white/10',
              i === 0 && aberta && 'bg-white/15'
            )}
          >
            <span className={cn('size-6 shrink-0 rounded-full bg-(--dot)', i !== 0 && 'opacity-60')} />
            <span
              className={cn(
                'text-sm font-medium whitespace-nowrap text-(--dot) transition-all duration-200',
                aberta ? 'translate-x-0 opacity-100 delay-150' : '-translate-x-2 opacity-0'
              )}
            >
              {n}
            </span>
          </button>
        ))}
        <button
          onClick={() => setAberta((a) => !a)}
          title={aberta ? 'Recolher' : 'Expandir'}
          className='mt-auto flex size-10 items-center justify-center rounded-xl text-lg text-(--dot) transition-colors hover:bg-white/10'
        >
          <span className={cn('transition-transform duration-300', aberta && 'rotate-180')}>»</span>
        </button>
      </aside>

      {/* Painel de tarefas */}
      <section className='hidden w-64 flex-col overflow-hidden rounded-2xl bg-white shadow-lg lg:flex'>
        <div className='flex items-center justify-between bg-(--rail) px-4 py-3 text-(--dot)'>
          <span className='font-semibold'>Tarefas</span>
          <span className='rounded-full bg-white/25 px-2 text-sm'>
            {tarefas.length - feitas.length}
          </span>
        </div>
        <ul className='space-y-1 p-3'>
          {tarefas.map((t) => (
            <li key={t}>
              <label className='flex cursor-pointer items-center justify-between gap-2 rounded-lg px-2 py-2 text-sm hover:bg-(--soft)'>
                <span className={cn(feitas.includes(t) && 'line-through opacity-50')}>{t}</span>
                <Checkbox checked={feitas.includes(t)} onCheckedChange={() => toggle(t)} />
              </label>
            </li>
          ))}
        </ul>
      </section>

      {/* Calendário */}
      <main className='flex flex-1 flex-col overflow-hidden rounded-2xl bg-white shadow-lg'>
        <header className='px-6 pt-5 pb-3'>
          <h1 className='text-3xl font-extrabold'>Horário</h1>
        </header>

        <div className='flex flex-wrap items-center justify-between gap-3 border-y border-(--line) bg-(--soft)/50 px-6 py-4'>
          <div className='flex gap-2'>
            {['Semana', 'Mês', 'Dia'].map((v) => (
              <button key={v} className={cn(btn, vista === v ? ativo : inativo)} onClick={() => setVista(v)}>
                {v}
              </button>
            ))}
          </div>
          <div className='flex flex-wrap gap-2'>
            {Object.keys(paleta.disc).map((d) => (
              <button
                key={d}
                className={cn(btn, filtro === d ? ativo : inativo)}
                onClick={() => setFiltro(filtro === d ? null : d)}
              >
                {d}
              </button>
            ))}
          </div>
        </div>

        <div className='overflow-auto p-4'>
          <div className='grid min-w-[720px] grid-cols-[60px_repeat(5,1fr)]'>
            <div />
            {dias.map((d) => (
              <div key={d} className='pb-2 text-center text-sm font-semibold'>
                {d}
              </div>
            ))}
            {horas.map((h, hi) => (
              <div key={h} className='contents'>
                <div className='border-t border-(--line) pt-3 text-xs opacity-60'>{h}</div>
                {dias.map((_, di) => (
                  <div key={di} className='space-y-2 border-t border-l border-(--line) p-2'>
                    {aulas
                      .filter(([d, hr, disc]) => d === di && hr === hi && (!filtro || filtro === disc))
                      .map(([, , disc, info], i) => {
                        const [cor, texto] = paleta.disc[disc];
                        return (
                          <button
                            key={i}
                            onClick={() => toast(`${disc} · ${dias[di]} ${h}`, { description: info })}
                            style={{
                              background: `color-mix(in srgb, ${cor} 16%, white)`,
                              borderLeftColor: cor,
                              color: texto
                            }}
                            className='w-full rounded-lg border-l-4 px-3 py-2 text-left transition hover:brightness-95'
                          >
                            <div className='text-sm font-semibold'>{disc}</div>
                            <div className='text-xs opacity-80'>{info}</div>
                          </button>
                        );
                      })}
                  </div>
                ))}
              </div>
            ))}
          </div>
        </div>
      </main>

      {/* Seletor de paleta */}
      <div className='fixed right-6 bottom-6 flex gap-1 rounded-full bg-white p-1 shadow-xl'>
        {paletas.map((pl, i) => (
          <button
            key={pl.nome}
            title={pl.nome}
            onClick={() => setP(i)}
            className={cn(
              'size-9 rounded-full text-sm font-bold transition',
              p === i ? 'bg-(--accent) text-(--accent-fg)' : 'hover:bg-(--soft)'
            )}
          >
            {i + 1}
          </button>
        ))}
      </div>
    </div>
  );
}
